import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.CD3qHYUq.js";import{d as i,f as a}from"./chunks/assets.00tzVH5c.js";var o=JSON.parse(`{"title":"Architecture","description":"In this page we give an architecture overview on how BullMQ is implemented, from the lifecycle of a job to the backends that store it in Redis™ or PostgreSQL.","frontmatter":{"description":"In this page we give an architecture overview on how BullMQ is implemented, from the lifecycle of a job to the backends that store it in Redis™ or PostgreSQL."},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1793136727000}`),s={name:`guide/architecture.md`};function c(t,o,s,c,l,u){return r(),e(`div`,null,[...o[0]||=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>In order to use the full potential of BullMQ queues, it is important to understand the lifecycle of a job. From the moment a producer calls the <a href="https://docs.bullmq.io/api/classes/v6.Queue.html#add" target="_blank" rel="noreferrer"><code>add</code></a> method on a <code>Queue</code> instance, a job enters a lifecycle where it will be in different states, until its completion or failure (although technically a failed job could be retried and get a new lifecycle).</p><figure><img src="`+a+`" alt="Diagram showing the lifecycle of a job in a queue, including wait, prioritized, delayed, active, completed, and failed states"><figcaption><p>Lifecycle of a job - Queue</p></figcaption></figure><p>When a job is added to a queue it can be in one of three states:</p><ul><li><strong>“wait”</strong>: a waiting list, where all jobs must enter before they can be processed.</li><li><strong>“prioritized”</strong>: implies that a job with higher priority will be processed first.</li><li><strong>“delayed”</strong>: implies that the job is waiting for some timeout or to be promoted for being processed. These jobs are not processed directly, but instead are placed at the beginning of the waiting list, or in a prioritized set, and processed as soon as a worker is idle.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Note that prioritized jobs use values from <code>1</code> to <code>2^21 - 1</code> (2 097 151), where a lower number is always a higher priority than higher numbers. This follows a similar standard as in Unix processes (<a href="https://en.wikipedia.org/wiki/Nice_(Unix)" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Nice_(Unix)</a>), where a higher number means less priority. A <code>priority</code> of <code>0</code> means no explicit priority is set, but since those jobs are always processed before any prioritized job, you can effectively think of <code>0</code> as the highest priority of all.</p></div><p>The next state for a job is the <strong>“active”</strong> state. The active state is represented by a set, and are jobs that are currently being processed (i.e. they are running in the <code>process</code> function explained in the previous chapter). A job can be in the active state for an unlimited amount of time until the process is completed or an exception is thrown so that the job will end in either the <strong>“completed”</strong> or the <strong>“failed”</strong> status.</p><p>Another way to add a job is by the <a href="https://docs.bullmq.io/api/classes/v6.FlowProducer.html#add" target="_blank" rel="noreferrer"><code>add</code></a> method on a flow producer instance.</p><figure><img src="`+i+`" alt="Diagram showing the lifecycle of a job in a flow producer, including wait, prioritized, delayed, waiting-children, active, completed, and failed states"><figcaption><p>Lifecycle of a job - Flow Producer</p></figcaption></figure><p>When a job is added by a flow producer, it can be in one of three states, it can either be in the <strong>“wait”</strong> or <strong>“prioritized“</strong> or <strong>“delayed“</strong> status, when there aren&#39;t children, or it can be in a <strong>“waiting-children”</strong> status: a waiting-children status implies that the job is waiting for all its children to be completed, however, a waiting-children job will not be processed directly, instead it will be placed at the waiting list or at delayed set (if <code>delay</code> is provided) or at prioritized set (if <code>delay</code> is 0 and <code>priority</code> is greater than 0) as soon as the last child is marked as completed.</p><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to “Backends”">​</a></h2><p>The lifecycle described above is the same regardless of where the jobs are stored. BullMQ is built in layers:</p><ol><li><strong>High-level classes</strong> (<code>Queue</code>, <code>Worker</code>, <code>QueueEvents</code>, <code>FlowProducer</code>, …) implement the public API. They are datastore agnostic and only depend on the backend contract (<a href="https://docs.bullmq.io/api" target="_blank" rel="noreferrer"><code>IQueueBackend</code></a>).</li><li><strong>Backends</strong> implement every queue operation, such as adding a job, moving it to active, extending its lock or blocking until a new job is available, and perform each state transition atomically: <ul><li>The <strong>Redis™ backend</strong> (default) implements every operation as a Lua script, so each state transition runs atomically inside Redis. Workers block on a marker key, so they are notified immediately when a job is available without polling. It works with any of the supported Redis clients and with compatible servers such as Valkey and Dragonfly.</li><li>The <strong>PostgreSQL backend</strong> stores jobs in regular tables and implements every operation as a SQL function running in a transaction. Workers block on a dedicated <code>LISTEN</code> connection and are woken up by producers using <code>NOTIFY</code>. See <a href="./postgresql#how-it-works">PostgreSQL backend</a> for more details.</li></ul></li><li><strong>Datastore clients</strong> handle the connections, such as ioredis, node-redis, Bun&#39;s Redis client or Valkey GLIDE for Redis, and node-postgres for PostgreSQL. See <a href="./connections">Connections</a>.</li></ol><p>The Lua and SQL scripts are shared by all the BullMQ SDKs (TypeScript, Python, Elixir, Rust, .NET and PHP), which are thin layers on top of them. This is what guarantees identical semantics across languages, and what makes it possible to add jobs from one language and process them from another, as long as they use the same backend.</p>`,14)]])}var l=t(s,[[`render`,c]]);export{o as __pageData,l as default};